-- Email verification, invitations and membership protection.
-- FRD refs: ACC-001 (verification), ACC-005 (invitations, suspend/remove),
-- §6 matrix (who may invite whom), §16, AC-ACC-001.2.
-- Tokens are random 32-byte values generated by the API; only their SHA-256
-- hashes are stored. The app role has no direct access to the token tables.

CREATE FUNCTION app_email_verified() RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, pg_temp AS $$
  SELECT EXISTS (SELECT 1 FROM users WHERE id = app_user_id() AND email_verified_at IS NOT NULL)
$$;
GRANT EXECUTE ON FUNCTION app_email_verified() TO upfixy_app;

-- -------------------------------------------------------- email verification
CREATE TABLE email_verification_tokens (
  id         bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  user_id    uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  token_hash text NOT NULL UNIQUE CHECK (token_hash ~ '^[0-9a-f]{64}$'),
  expires_at timestamptz NOT NULL,
  used_at    timestamptz,
  created_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE email_verification_tokens ENABLE ROW LEVEL SECURITY; -- no policies: app role sees nothing

CREATE FUNCTION issue_email_verification(p_hash text, p_minutes integer) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $$
BEGIN
  IF app_user_id() IS NULL THEN RAISE EXCEPTION 'no authenticated user'; END IF;
  IF p_minutes NOT BETWEEN 5 AND 2880 THEN RAISE EXCEPTION 'invalid lifetime'; END IF;
  IF app_email_verified() THEN RAISE EXCEPTION 'email already verified' USING ERRCODE = '22023'; END IF;
  -- Only the newest link works.
  UPDATE email_verification_tokens SET used_at = now() WHERE user_id = app_user_id() AND used_at IS NULL;
  INSERT INTO email_verification_tokens(user_id, token_hash, expires_at)
  VALUES (app_user_id(), p_hash, now() + make_interval(mins => p_minutes));
END $$;

-- Callable without a session: the link in the email is the credential.
CREATE FUNCTION confirm_email_verification(p_hash text) RETURNS uuid
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $$
DECLARE uid uuid;
BEGIN
  UPDATE email_verification_tokens SET used_at = now()
   WHERE token_hash = p_hash AND used_at IS NULL AND expires_at > now()
  RETURNING user_id INTO uid;
  IF uid IS NOT NULL THEN
    UPDATE users SET email_verified_at = coalesce(email_verified_at, now()) WHERE id = uid;
  END IF;
  RETURN uid;
END $$;

GRANT EXECUTE ON FUNCTION issue_email_verification(text, integer), confirm_email_verification(text) TO upfixy_app;

-- --------------------------------------------------------------- invitations
CREATE TABLE invitations (
  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  email       citext NOT NULL,
  role        member_role NOT NULL CHECK (role <> 'owner'),
  client_id   uuid,
  token_hash  text NOT NULL UNIQUE CHECK (token_hash ~ '^[0-9a-f]{64}$'),
  invited_by  uuid NOT NULL,
  expires_at  timestamptz NOT NULL,
  accepted_at timestamptz,
  accepted_by uuid REFERENCES users(id),
  revoked_at  timestamptz,
  created_at  timestamptz NOT NULL DEFAULT now(),
  FOREIGN KEY (workspace_id, client_id) REFERENCES clients(workspace_id, id) ON DELETE CASCADE,
  FOREIGN KEY (workspace_id, invited_by) REFERENCES memberships(workspace_id, user_id),
  -- Client-side roles always belong to a specific client.
  CHECK (role NOT IN ('client_owner', 'client_staff') OR client_id IS NOT NULL),
  CHECK (expires_at <= created_at + interval '14 days')
);
CREATE UNIQUE INDEX invitations_one_open ON invitations(workspace_id, email)
  WHERE accepted_at IS NULL AND revoked_at IS NULL;

ALTER TABLE invitations ENABLE ROW LEVEL SECURITY;

-- §6 "Invite / change roles": owner and admin invite anyone but an owner;
-- a client owner may invite client staff for their own client only.
CREATE FUNCTION app_can_invite(p_role member_role, p_client uuid) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, pg_temp AS $$
  SELECT app_email_verified() AND p_role <> 'owner' AND (
    app_role() IN ('owner', 'admin')
    OR (app_role() = 'client_owner' AND p_role = 'client_staff' AND p_client IS NOT NULL AND app_is_assigned(p_client))
  )
$$;
GRANT EXECUTE ON FUNCTION app_can_invite(member_role, uuid) TO upfixy_app;

CREATE POLICY inv_select ON invitations FOR SELECT TO upfixy_app
  USING (workspace_id = app_workspace_id() AND (
    app_role() IN ('owner', 'admin') OR (app_role() = 'client_owner' AND invited_by = app_user_id())));
CREATE POLICY inv_insert ON invitations FOR INSERT TO upfixy_app
  WITH CHECK (workspace_id = app_workspace_id() AND invited_by = app_user_id() AND app_can_invite(role, client_id));
CREATE POLICY inv_revoke ON invitations FOR UPDATE TO upfixy_app
  USING (workspace_id = app_workspace_id() AND accepted_at IS NULL AND (
    app_role() IN ('owner', 'admin') OR invited_by = app_user_id()))
  WITH CHECK (workspace_id = app_workspace_id());

GRANT SELECT (id, workspace_id, email, role, client_id, invited_by, expires_at, accepted_at, revoked_at, created_at)
  ON invitations TO upfixy_app;
GRANT INSERT ON invitations TO upfixy_app;
GRANT UPDATE (revoked_at) ON invitations TO upfixy_app;

-- Accepting requires a signed-in user whose VERIFIED email matches the invite.
CREATE FUNCTION accept_invitation(p_hash text) RETURNS uuid
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $$
DECLARE inv invitations; me users; existing memberships;
BEGIN
  IF app_user_id() IS NULL THEN RAISE EXCEPTION 'no authenticated user'; END IF;
  SELECT * INTO inv FROM invitations
   WHERE token_hash = p_hash AND accepted_at IS NULL AND revoked_at IS NULL AND expires_at > now()
   FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'invitation is not valid' USING ERRCODE = 'P0002'; END IF;

  SELECT * INTO me FROM users WHERE id = app_user_id();
  IF me.email_verified_at IS NULL THEN
    RAISE EXCEPTION 'verify your email before accepting' USING ERRCODE = '42501';
  END IF;
  IF me.email <> inv.email THEN
    RAISE EXCEPTION 'invitation was sent to a different email' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO existing FROM memberships WHERE workspace_id = inv.workspace_id AND user_id = me.id FOR UPDATE;
  IF FOUND AND existing.suspended_at IS NULL THEN
    RAISE EXCEPTION 'already a member of this workspace' USING ERRCODE = '23505';
  ELSIF FOUND THEN
    UPDATE memberships SET role = inv.role, suspended_at = NULL
     WHERE workspace_id = inv.workspace_id AND user_id = me.id;
  ELSE
    INSERT INTO memberships(workspace_id, user_id, role) VALUES (inv.workspace_id, me.id, inv.role);
  END IF;
  IF inv.client_id IS NOT NULL THEN
    INSERT INTO client_assignments(workspace_id, client_id, user_id)
    VALUES (inv.workspace_id, inv.client_id, me.id) ON CONFLICT DO NOTHING;
  END IF;
  UPDATE invitations SET accepted_at = now(), accepted_by = me.id WHERE id = inv.id;
  RETURN inv.workspace_id;
END $$;
GRANT EXECUTE ON FUNCTION accept_invitation(text) TO upfixy_app;

-- -------------------------------------------------- membership protection
-- Memberships are created only by create_workspace() and accept_invitation().
-- Removal is suspension (rows are referenced by approvals and tickets).
REVOKE INSERT, DELETE, UPDATE ON memberships FROM upfixy_app;
GRANT UPDATE (role, suspended_at) ON memberships TO upfixy_app;

CREATE FUNCTION memberships_guard() RETURNS trigger
LANGUAGE plpgsql SET search_path = public, pg_temp AS $$
DECLARE owners_left integer;
BEGIN
  IF current_user = 'upfixy_app' THEN
    -- Only an owner may change or suspend an owner, or make someone an owner.
    IF (OLD.role = 'owner' OR NEW.role = 'owner') AND app_role() IS DISTINCT FROM 'owner' THEN
      RAISE EXCEPTION 'only an owner can change an owner' USING ERRCODE = '42501';
    END IF;
  END IF;
  -- A workspace always keeps at least one active owner.
  IF OLD.role = 'owner' AND OLD.suspended_at IS NULL
     AND (NEW.role <> 'owner' OR NEW.suspended_at IS NOT NULL) THEN
    SELECT count(*) INTO owners_left FROM memberships
     WHERE workspace_id = OLD.workspace_id AND role = 'owner' AND suspended_at IS NULL AND user_id <> OLD.user_id;
    IF owners_left = 0 THEN
      RAISE EXCEPTION 'a workspace must keep at least one owner' USING ERRCODE = '23514';
    END IF;
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER memberships_guard BEFORE UPDATE ON memberships
  FOR EACH ROW EXECUTE FUNCTION memberships_guard();

-- Suspension removes client assignments and unassigns open tickets.
CREATE FUNCTION memberships_after_suspend() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $$
BEGIN
  IF NEW.suspended_at IS NOT NULL AND OLD.suspended_at IS NULL THEN
    DELETE FROM client_assignments WHERE workspace_id = NEW.workspace_id AND user_id = NEW.user_id;
    UPDATE tickets SET assignee_id = NULL, version = version + 1
     WHERE workspace_id = NEW.workspace_id AND assignee_id = NEW.user_id AND state NOT IN ('resolved', 'closed');
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER memberships_after_suspend AFTER UPDATE ON memberships
  FOR EACH ROW EXECUTE FUNCTION memberships_after_suspend();

-- Suspended members' pending invitations stop working.
CREATE FUNCTION memberships_revoke_invites() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $$
BEGIN
  IF NEW.suspended_at IS NOT NULL AND OLD.suspended_at IS NULL THEN
    UPDATE invitations SET revoked_at = now()
     WHERE workspace_id = NEW.workspace_id AND invited_by = NEW.user_id
       AND accepted_at IS NULL AND revoked_at IS NULL;
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER memberships_revoke_invites AFTER UPDATE ON memberships
  FOR EACH ROW EXECUTE FUNCTION memberships_revoke_invites();

-- Team list for owner/admin: members with emails (users RLS already restricts rows).
CREATE VIEW workspace_members WITH (security_invoker = true) AS
  SELECT m.workspace_id, m.user_id, u.email, m.role, m.suspended_at, m.created_at,
         u.email_verified_at IS NOT NULL AS email_verified, u.mfa_enabled_at IS NOT NULL AS mfa_enabled
    FROM memberships m JOIN users u ON u.id = m.user_id;
GRANT SELECT ON workspace_members TO upfixy_app;
